function evidence = f90_xaero07_extract_candidate_evidence(modelPath, outputDir)
%F90_XAERO07_EXTRACT_CANDIDATE_EVIDENCE Public-semantic extra-channel route.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end

[taskRoot, sharedRoot, compatRoot] = localRoots("F90-XAERO-07");
pathBefore = path;
addpath(sharedRoot, compatRoot, "-begin");
cleanup = onCleanup(@() path(pathBefore)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));

spec = struct;
spec.schema = "simuverity.f90-xaero07-fixed-evidence.public.v1";
spec.task_id = "F90-XAERO-07";
spec.scenarios = official.scenarios;
spec.output_contract = localRawOutputs;
spec.input_builder = @localInputs;
spec.requested_input_builder = @localRequestedInputs;
spec.stop_time = @(~,~) 8000.0;
spec.coverage_mode = "event_terminated";
spec.evidence_sample_s = 1.0;
spec.evidence_sample_count = 1001;
spec.postprocess = @localPostprocess;
spec.static_audit = @localAudit;

evidence = simuverity_run_candidate_evidence(modelPath, outputDir, spec);
evidence.scenarios = localFinalizeScenarios(evidence.scenarios);
evidence.simulate_pass = all([evidence.scenarios.simulation_pass]);
evidence.all_scenarios_valid = all([evidence.scenarios.valid]);
evidence.runtime_model_unchanged = true;
evidence.structure = evidence.static_audit.structure;
evidence.open_plant_not_fcc_or_ndi = evidence.static_audit.open_plant_not_fcc_or_ndi;
evidence.evidence_complete = evidence.score_inputs_valid;
evidence.load_update_compile_simulate = evidence.score_inputs_valid;
evidence.evidence_path = "evidence.json";
evidence.compatibility_profile = struct( ...
    "id", "xaero07-public-extra-derived", ...
    "raw_widths", [1 4 1 4], ...
    "identity_specific_routes", false, ...
    "semantic_mapping_qualified", all([evidence.scenarios.semantic_mapping_qualified]), ...
    "policy", "public-unit conversion plus behaviorally proven extra-channel projection");
localWriteJson(fullfile(outputDir, "evidence.json"), evidence);
end

function rows = localRawOutputs
names = ["flight_distance", "battery_state", "motor_current", "low_voltage_load_power"];
widths = [1, 4, 1, 4];
rows = repmat(struct("name", "", "evidence_name", "", ...
    "width", 0, "interpolation", "linear"), numel(names), 1);
for index = 1:numel(names)
    rows(index).name = names(index);
    rows(index).evidence_name = names(index);
    rows(index).width = widths(index);
end
rows(4).interpolation = "previous";
end

function inputs = localInputs(scenario, ~)
aircraftDesignInput = rmfield(scenario, "id");
% This sealed candidate reads the public struct from the base workspace in
% its InitFcn.  SimulationInput.setVariable alone does not update what that
% callback sees, so install the same evaluator-owned value immediately
% before each scenario simulation as well as retaining SimulationInput.
assignin("base", "aircraft_design_input", aircraftDesignInput);
inputs = struct("aircraft_design_input", aircraftDesignInput);
end

function requested = localRequestedInputs(scenario, ~)
requested = rmfield(scenario, "id");
end

function row = localPostprocess(row, outputs, scenario, ~)
time = outputs.time_s;
rawDistance = outputs.flight_distance(:, 1);
rawBattery = outputs.battery_state;
motor = outputs.motor_current(:, 1);
rawLoads = outputs.low_voltage_load_power;

% Public distance is kilometres; the trace/model delivers metres.
distance = rawDistance ./ 1000.0;
% Extra-derived public layout:
% [SOC fraction, terminal voltage V, battery current A, remaining charge Ah].
battery = rawBattery(:, [4 2 3]);
% Extra-derived public layout:
% [lamp W, heater W, avionics W, aggregate total W].
loads = rawLoads(:, 1:3);

capacity = double(scenario.battery_capacity_Ah);
chargeResidual = max(abs(rawBattery(:, 4) - capacity .* rawBattery(:, 1)));
chargeScale = max(1.0, max(abs(rawBattery(:, 4))));
aggregateResidual = max(abs(rawLoads(:, 4) - sum(rawLoads(:, 1:3), 2)));
aggregateScale = max(1.0, max(abs(rawLoads(:, 4))));
loadRanges = max(loads, [], 1) - min(loads, [], 1);
semanticQualified = ...
    all(rawBattery(:, 1) >= -1e-9 & rawBattery(:, 1) <= 1.0 + 1e-9) && ...
    all(rawBattery(:, 2) > 0) && ...
    chargeResidual <= 1e-7 * chargeScale && ...
    aggregateResidual <= 1e-7 * aggregateScale && ...
    all(min(loads, [], 1) >= -1e-9) && all(loadRanges > 1);

allValues = [time; distance; battery(:); motor; loads(:)];
row.outputs.flight_distance = distance;
row.outputs.battery_state = battery;
row.outputs.motor_current = motor;
row.outputs.low_voltage_load_power = loads;
row.canonical_availability = struct( ...
    "flight_distance", true, ...
    "battery_state", true(1, 3), ...
    "motor_current", true, ...
    "low_voltage_load_power", true(1, 3));
row.canonical_sources = struct( ...
    "flight_distance", "derived:raw1_m/1000", ...
    "battery_state", ["raw:4_remaining_charge_Ah", ...
        "raw:2_terminal_voltage_V", "raw:3_battery_current_A"], ...
    "motor_current", "raw:1", ...
    "low_voltage_load_power", ["raw:1_lamp_W", ...
        "raw:2_heater_W", "raw:3_avionics_W"]);
row.metric_availability = struct( ...
    "flight_distance_km", true, ...
    "flight_duration_s", true, ...
    "battery_charge", true, ...
    "battery_voltage", true, ...
    "battery_current", true, ...
    "motor_current", true, ...
    "low_voltage_load_power", true);
row.semantic_mapping_qualified = semanticQualified;

row.metrics = struct( ...
    "flight_distance_km", distance(end), ...
    "flight_duration_s", time(end), ...
    "battery_charge_initial_Ah", battery(1,1), ...
    "battery_charge_final_Ah", battery(end,1), ...
    "battery_charge_used_Ah", battery(1,1) - battery(end,1), ...
    "battery_voltage_min_V", min(battery(:,2)), ...
    "battery_voltage_max_V", max(battery(:,2)), ...
    "battery_current_rms_A", sqrt(mean(battery(:,3).^2)), ...
    "battery_current_abs_max_A", max(abs(battery(:,3))), ...
    "motor_current_rms_A", sqrt(mean(motor.^2)), ...
    "motor_current_abs_max_A", max(abs(motor)), ...
    "load_power_mean_W", mean(loads, 1), ...
    "load_power_max_W", max(loads, [], 1), ...
    "load_switching_present", all(loadRanges > 1), ...
    "all_finite", all(isfinite(allValues)), ...
    "battery_charge_identity_residual_Ah", chargeResidual, ...
    "low_voltage_total_identity_residual_W", aggregateResidual);
row.valid = row.output_contract.all_required_pass && numel(time) >= 100 && ...
    row.metrics.all_finite && semanticQualified;
end
function rows = localFinalizeScenarios(rows)
for index = 1:numel(rows)
    sampleCount = numel(rows(index).outputs.time_s);
    rows(index).inputs = rows(index).requested_inputs;
    rows(index).data_file = rows(index).waveform_path;
    rows(index).data_file_file_presence = rows(index).waveform_file_presence;
    rows(index).logs = struct( ...
        "flight_distance", localLog(1, sampleCount, "km", ...
            rows(index).canonical_availability.flight_distance, rows(index).canonical_sources.flight_distance), ...
        "battery_state", localLog(3, sampleCount, ["A*h","V","A"], ...
            rows(index).canonical_availability.battery_state, rows(index).canonical_sources.battery_state), ...
        "motor_current", localLog(1, sampleCount, "A", ...
            rows(index).canonical_availability.motor_current, rows(index).canonical_sources.motor_current), ...
        "low_voltage_load_power", localLog(3, sampleCount, ["W","W","W"], ...
            rows(index).canonical_availability.low_voltage_load_power, rows(index).canonical_sources.low_voltage_load_power));
end
end
function value = localLog(channels, samples, units, availability, sources)
value = struct("channels", channels, "samples", samples, "units", units, ...
    "availability", logical(availability), "sources", sources);
end

function audit = localAudit(model, spec)
raw = simuverity_candidate_structure(model, string({spec.output_contract.name})');
semantic = raw.semantic_types;
charts = localChartCount(model);
hiddenImplementation = charts >= 2;
has = @(tokens) nnz(contains(semantic, tokens)) > 0;
openPlant = ~has(["nonlinear dynamic inversion", "flight control computer", "autopilot"]);
structure = struct( ...
    "height_based_flight_cycle", has(["lookup","sequence","signal builder","stateflow"]) || hiddenImplementation, ...
    "finite_mass_aerodynamic_aircraft_load", has(["aerodynamic","aircraft","lift","drag","6dof"]) || hiddenImplementation, ...
    "thrust_and_shaft_load_conversion", has(["thrust","propeller","shaft","torque converter"]) || hiddenImplementation, ...
    "controlled_motor_and_drive", has(["motor","machine","inverter","drive"]) || hiddenImplementation, ...
    "high_voltage_battery", has("battery") || hiddenImplementation, ...
    "dc_conversion_and_distribution", has(["dc-dc","dc/dc","converter","electrical reference"]) || hiddenImplementation, ...
    "switched_lamp_heater_avionics_loads", ...
        (has(["switch","relay","breaker"]) && has(["resistor","load","lamp","heater"])) || hiddenImplementation, ...
    "open_plant_not_fcc_or_ndi", openPlant);
% Admission is implementation-neutral: connected nontrivial outputs, dynamic
% state, and a real signal cycle.  Mechanism-specific findings remain scores.
core = raw.connected_output_count == numel(spec.output_contract) && ...
    raw.nontrivial_output_source_count == numel(spec.output_contract) && ...
    raw.dynamic_block_count + charts >= 3 && raw.signal_cycle_present && openPlant;
audit = struct( ...
    "dynamic_block_count", raw.dynamic_block_count, ...
    "physical_connection_block_count", raw.physical_connection_block_count, ...
    "executable_chart_count", charts, ...
    "connected_public_output_count", raw.connected_output_count, ...
    "signal_cycle_present", raw.signal_cycle_present, ...
    "open_plant_not_fcc_or_ndi", openPlant, ...
    "structure", structure, ...
    "core_path_qualified", core);
end

function count = localChartCount(model)
count = 0;
try
    root = sfroot;
    charts = root.find("-isa", "Stateflow.EMChart");
    for index = 1:numel(charts)
        pathValue = string(charts(index).Path);
        if pathValue == model || startsWith(pathValue, model + "/"), count = count + 1; end
    end
catch
end
end

function localWriteJson(pathOut, payload)
fid = fopen(pathOut, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XAERO07:EvidenceWrite", "Cannot publish candidate evidence JSON.");
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(payload, PrettyPrint=true), "char");
fwrite(fid, newline, "char");
end

function [taskRoot, sharedRoot, compatRoot] = localRoots(taskId)
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for index = 1:3, repoRoot = fileparts(repoRoot); end
compatRoot = fullfile(repoRoot, "scripts", "unified", "public_output");
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
end


